def update_production_start_year(curr, debug=False):
	sql_update = \
		'''
    UPDATE tblUSWell_Parameters SET Production_Start_Year=b.Production_Start_Year
    FROM tblUSWell_Parameters a,
    (SELECT API_Number, MIN([Period]) AS Production_Start_Year FROM tblUSWell_Production_Forecast WHERE (ISNULL(Gas_Total_mcf,0)+ISNULL(Oil_Total_bbl,0)+ISNULL(Condensate_Total_bbl,0)+ISNULL(NGL_Total_bbl,0)) > 0 GROUP BY API_Number) b
    WHERE a.API_Number=b.API_Number
    '''
	curr.execute(sql_update)
	gd.commit(curr)


